head.script:
scwin.trigger1_onclick = function(e) {
    var options = {
        type: "1",
        headerExist: "0",
        useModalDisable: "true"
    };
    gridView1.advancedExcelUpload(options);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
